const q = msg.req.query;
const conditions = [];
if (q.eventtype) conditions.push("eventtype = '" + q.eventtype.replace(/'/g,"''") + "'");
if (q.plate) conditions.push("(message LIKE '%" + q.plate.replace(/'/g,"''") + "%' OR " +
  "parking_session_id IN (SELECT id FROM parking_sessions WHERE plate = '" + q.plate.replace(/'/g,"''") + "'))");
if (q.from) conditions.push("timestamp >= '" + q.from + "'");
if (q.to) conditions.push("timestamp <= '" + q.to + "'");
const where = conditions.length > 0 ? 'WHERE ' + conditions.join(' AND ') : '';
const limit = parseInt(q.limit) || 100;
const offset = parseInt(q.offset) || 0;
msg.topic = 'SELECT id, timestamp, eventtype, source, message, parking_session_id FROM event_logs ' + where + ' ORDER BY id DESC LIMIT ' + limit + ' OFFSET ' + offset + ';';
return msg;

msg.payload = msg.payload || [];
msg.headers = { 'Content-Type': 'application/json' };
msg.statusCode = 200;
return msg;

// Aktuellen Preis fuer ALLE offenen Sessions berechnen und in amount_due speichern.
// (1 EUR je angefangener Stunde ab entry_time)
msg.topic = "UPDATE parking_sessions " +
  "SET amount_due = MAX(1, CAST((((julianday('now') - julianday(entry_time)) * 1440.0) + 59.9999) / 60.0 AS INTEGER)) * 1.0 " +
  "WHERE exit_time IS NULL;";
return msg;

// amount_due kommt jetzt bereits aktuell aus der Datenbank (siehe Query davor)
const rows = msg.payload || [];
msg.statusCode = 200;
msg.payload = rows.map(function(s) {
  return {
    id: s.id,
    plate: s.plate,
    entry_time: s.entry_time,
    amount_due: parseFloat(s.amount_due) || 0,
    amount_paid: parseFloat(s.amount_paid) || 0
  };
});
return msg;

const id = parseInt(msg.req.params.sessionId);
if (!id) {
  msg.statusCode = 400;
  msg.payload = JSON.stringify({error: 'Ungueltige sessionId'});
  msg.topic = 'SELECT 1 WHERE 0;'; // Bugfix: vorher blieb topic hier undefiniert
  return msg;
}
msg._session_id = id;
msg.topic = 'SELECT * FROM parking_sessions WHERE id = ' + id + ';';
return msg;

if (msg.statusCode) return msg; // Fehler aus vorherigen Nodes durchreichen

if (!msg.payload || msg.payload.length === 0) {
  msg.statusCode = 404;
  msg.payload = JSON.stringify({error: 'Session nicht gefunden'});
} else {
  msg.statusCode = 200;
  msg.payload = msg.payload[0];
}
return msg;

const id = parseInt(msg.req.params.sessionId);
const body = msg.req.body || {};
if (!id) {
  msg.statusCode = 400;
  msg.payload = JSON.stringify({error: 'Ungueltige sessionId'});
  msg.topic = 'SELECT 1 WHERE 0;';
  return msg;
}
const sets = [];
if (body.amount_paid !== undefined) sets.push('amount_paid = ' + parseFloat(body.amount_paid));
if (body.payment_time !== undefined) sets.push("payment_time = '" + String(body.payment_time).replace(/'/g,"''") + "'");
if (body.exit_valid_until !== undefined) sets.push("exit_valid_until = '" + String(body.exit_valid_until).replace(/'/g,"''") + "'");
if (sets.length === 0) {
  msg.statusCode = 400;
  msg.payload = JSON.stringify({error: 'Keine Felder angegeben'});
  msg.topic = 'SELECT 1 WHERE 0;';
  return msg;
}
msg._patch_session_id = id;
msg.topic = 'UPDATE parking_sessions SET ' + sets.join(', ') + ' WHERE id = ' + id + ';';
return msg;

if (msg.statusCode) return msg; // Validierungsfehler durchreichen statt ueberschreiben
msg.statusCode = 200;
msg.payload = JSON.stringify({success: true, session_id: msg._patch_session_id});
return msg;

msg.statusCode = 200;
msg.payload = msg.payload || [];
return msg;

const body = msg.req.body || {};
if (!body.name || !body.uid) {
  msg.statusCode = 400;
  msg.payload = JSON.stringify({error: 'name und uid erforderlich'});
  msg.topic = 'SELECT 1 WHERE 0;';
  return msg;
}
const active = body.active !== false ? 1 : 0;
msg.topic = "INSERT INTO user_admins (name, rfid_uid, role, active) VALUES ('" +
  body.name.replace(/'/g,"''") + "', '" + body.uid.replace(/'/g,"''") + "', 'admin', " + active + ");";
return msg;

if (msg.statusCode) return msg;
msg.statusCode = 201;
msg.payload = JSON.stringify({success: true});
return msg;

const uid = msg.req.params.uid;
const body = msg.req.body || {};
if (body.active === undefined) {
  msg.statusCode = 400;
  msg.payload = JSON.stringify({error: 'active erforderlich'});
  msg.topic = 'SELECT 1 WHERE 0;';
  return msg;
}
const active = body.active ? 1 : 0;
msg.topic = "UPDATE user_admins SET active = " + active + " WHERE rfid_uid = '" + uid.replace(/'/g,"''") + "';";
return msg;

if (msg.statusCode) return msg;
msg.statusCode = 200;
msg.payload = JSON.stringify({success: true});
return msg;

msg.statusCode = 200;
msg.payload = msg.payload || [];
return msg;

// Aktuellen Preis fuer ALLE offenen Sessions berechnen und in amount_due speichern.
msg.topic = "UPDATE parking_sessions " +
  "SET amount_due = MAX(1, CAST((((julianday('now') - julianday(entry_time)) * 1440.0) + 59.9999) / 60.0 AS INTEGER)) * 1.0 " +
  "WHERE exit_time IS NULL;";
return msg;

// amount_due kommt jetzt bereits aktuell aus der Datenbank (siehe Query davor)
const rows = msg.payload || [];
msg.statusCode = 200;
msg.payload = rows.map(function(s) {
  const due = parseFloat(s.amount_due) || 0;
  const paid = parseFloat(s.amount_paid) || 0;
  return {
    session_id: s.session_id,
    plate: s.plate,
    entry_time: s.entry_time,
    amount_due: due,
    amount_paid: paid,
    remaining_amount: Math.max(0, Math.round((due - paid) * 100) / 100)
  };
});
return msg;

const plate = msg.req.params.plate.trim().toUpperCase();
msg._req_plate = plate;
msg.topic = "SELECT id as session_id, plate, entry_time, amount_paid FROM parking_sessions WHERE plate = '" + plate.replace(/'/g,"''") + "' AND exit_time IS NULL ORDER BY id DESC LIMIT 1;";
return msg;

// amount_due kommt jetzt bereits aktuell aus der Datenbank (siehe Query davor)
const rows = msg.payload || [];
if (rows.length === 0) {
  msg.statusCode = 404;
  msg.payload = JSON.stringify({error: 'Keine aktive Session fuer dieses Kennzeichen'});
  return msg;
}
const s = rows[0];
const due = parseFloat(s.amount_due) || 0;
const paid = parseFloat(s.amount_paid) || 0;
msg.statusCode = 200;
msg.payload = {
  session_id: s.id,
  plate: s.plate,
  entry_time: s.entry_time,
  amount_due: due,
  amount_paid: paid,
  remaining_amount: Math.max(0, Math.round((due - paid) * 100) / 100)
};
return msg;

const body = msg.req.body || {};
const plate = (body.plate || '').trim().toUpperCase();
const amountNow = parseFloat(body.amount_paid_now);
if (!plate || isNaN(amountNow) || amountNow <= 0) {
  msg.statusCode = 400;
  msg.payload = JSON.stringify({error: 'plate und amount_paid_now (>0) erforderlich'});
  msg.topic = 'SELECT 1 WHERE 0;';
  return msg;
}
msg._pay_plate = plate;
msg._pay_amount_now = amountNow;
msg.topic = "SELECT id, plate, entry_time, amount_due, amount_paid FROM parking_sessions " +
  "WHERE plate = '" + plate.replace(/'/g,"''") + "' AND exit_time IS NULL ORDER BY id DESC LIMIT 1;";
return msg;

if (msg.statusCode) { msg.topic = 'SELECT 1 WHERE 0;'; return msg; } // Validierung bereits fehlgeschlagen

const rows = msg.payload;
if (!rows || rows.length === 0) {
  msg.statusCode = 404;
  msg.payload = JSON.stringify({error: 'Keine aktive Session fuer ' + msg._pay_plate});
  msg.topic = 'SELECT 1 WHERE 0;';
  return msg;
}
const session = rows[0];

// Preis wurde bereits im GET-Flow berechnet und in amount_due gespeichert.
// Hier findet KEINE Neuberechnung anhand der Parkzeit mehr statt.
const amountDue = parseFloat(session.amount_due) || 0;
const amountPaidBefore = parseFloat(session.amount_paid) || 0;
const amountNow = msg._pay_amount_now;
const amountPaidTotal = Math.round((amountPaidBefore + amountNow) * 100) / 100;
const remaining = Math.max(0, Math.round((amountDue - amountPaidTotal) * 100) / 100);
const exitAllowed = amountPaidTotal >= amountDue;

const exitValidUntil = exitAllowed
  ? new Date(Date.now() + 15 * 60 * 1000).toISOString()
  : null;

msg._pay_result = {
  success: true,
  plate: session.plate,
  session_id: session.id,
  amount_due: amountDue,
  amount_paid_total: amountPaidTotal,
  remaining_amount: remaining,
  exit_allowed: exitAllowed
};

let sql = 'UPDATE parking_sessions SET amount_paid = ' + amountPaidTotal +
  ", payment_time = datetime('now')";
if (exitAllowed) {
  sql += ", exit_valid_until = '" + exitValidUntil + "'";
}
sql += ' WHERE id = ' + session.id + ';';
msg.topic = sql;
return msg;

if (msg.statusCode) { msg.topic = 'SELECT 1 WHERE 0;'; return msg; }
const r = msg._pay_result;
msg.topic = "INSERT INTO event_logs (eventtype, source, message, parking_session_id) VALUES " +
  "('PAYMENT_SUCCESS', 'rest_api', 'Zahlung fuer " + r.plate + ": " + r.amount_paid_total + " EUR (gesamt)', " + r.session_id + ");";
return msg;

if (msg.statusCode) return msg; // Fehler aus vorherigen Nodes durchreichen
msg.statusCode = 200;
msg.payload = msg._pay_result;
return msg;

const id = parseInt(msg.req.params.sessionId);
if (!id) {
  msg.statusCode = 400;
  msg.payload = JSON.stringify({error: 'Ungueltige sessionId'});
  msg.topic = 'SELECT 1 WHERE 0;';
  return msg;
}
msg._patch_id = id;
msg.topic = 'SELECT amount_due, amount_paid, exit_time FROM parking_sessions WHERE id = ' + id + ';';
return msg;

if (msg.statusCode) return msg; // Fehler aus vorherigen Nodes durchreichen

const rows = msg.payload || [];
const session = rows[0];
msg.statusCode = 200;
msg.payload = JSON.stringify({
  success: true,
  session_id: session.id,
  plate: session.plate,
  amount_due: session.amount_due,
  amount_paid: session.amount_paid,
  payment_time: session.payment_time,
  exit_valid_until: session.exit_valid_until
});
return msg;

msg.statusCode = 200;
msg.payload = msg.payload || [];
return msg;

const row = msg.payload && msg.payload[0] ? msg.payload[0] : {total_spots:0, occupied_spots:0};
msg.statusCode = 200;
msg.payload = {
  total_spots: row.total_spots,
  free_spots: row.total_spots - row.occupied_spots,
  occupied_spots: row.occupied_spots
};
return msg;

msg.topic = "SELECT id, plate, entry_time, amount_due, amount_paid FROM parking_sessions " +
  "WHERE exit_time IS NULL ORDER BY entry_time ASC;";
return msg;

if (msg.statusCode) return msg; // vorherige Validierung fehlgeschlagen -> durchreichen

function calcAmountDue(entryTime) {
  const entry = new Date(entryTime.replace(' ', 'T') + (entryTime.includes('T') ? '' : 'Z'));
  const diffMs = Date.now() - entry.getTime();
  const diffMinutes = diffMs / 1000 / 60;
  const hoursStarted = Math.max(1, Math.ceil(diffMinutes / 60));
  return Math.round(hoursStarted * 1.0 * 100) / 100;
}

const rows = msg.payload || [];
if (rows.length === 0 || rows[0].exit_time) {
  // Session existiert nicht oder ist bereits beendet: amount_due nicht neu berechnen
  msg.topic = 'UPDATE parking_sessions SET amount_due = amount_due WHERE id = ' + msg._session_id + ';';
  return msg;
}

const amountDue = calcAmountDue(rows[0].entry_time);
msg.topic = 'UPDATE parking_sessions SET amount_due = ' + amountDue + ' WHERE id = ' + msg._session_id + ';';
return msg;

if (msg.statusCode) return msg;
msg.topic = 'SELECT * FROM parking_sessions WHERE id = ' + msg._session_id + ';';
return msg;

msg.topic = "SELECT id as session_id, plate, entry_time, amount_due, amount_paid " +
  "FROM parking_sessions WHERE exit_time IS NULL ORDER BY entry_time ASC;";
return msg;

function calcAmountDue(entryTime) {
  const entry = new Date(entryTime.replace(' ', 'T') + (entryTime.includes('T') ? '' : 'Z'));
  const diffMs = Date.now() - entry.getTime();
  const diffMinutes = diffMs / 1000 / 60;
  const hoursStarted = Math.max(1, Math.ceil(diffMinutes / 60));
  return Math.round(hoursStarted * 1.0 * 100) / 100;
}

const rows = msg.payload || [];
if (rows.length === 0) {
  // Keine aktive Session gefunden: harmloses No-Op, Response-Node meldet 404
  msg._session_id = -1;
  msg.topic = 'UPDATE parking_sessions SET amount_due = amount_due WHERE id = -1;';
  return msg;
}

const session = rows[0];
msg._session_id = session.session_id;
const amountDue = calcAmountDue(session.entry_time);
msg.topic = 'UPDATE parking_sessions SET amount_due = ' + amountDue + ' WHERE id = ' + session.session_id + ';';
return msg;

msg.topic = "SELECT id, plate, entry_time, amount_due, amount_paid " +
  "FROM parking_sessions WHERE id = " + msg._session_id + ";";
return msg;

if (msg.statusCode) return msg; // ungueltige sessionId, bereits behandelt

const rows = msg.payload || [];
if (rows.length === 0) {
  msg.statusCode = 404;
  msg.payload = JSON.stringify({error: 'Session nicht gefunden'});
  return msg;
}

const session = rows[0];
if (session.exit_time) {
  msg.statusCode = 409;
  msg.payload = JSON.stringify({error: 'Session ist bereits ausgefahren, keine Zahlung mehr moeglich'});
  return msg;
}

// Offener Betrag = amount_due - amount_paid. Rein informativ, es findet
// HIER KEINE Neuberechnung des Preises anhand der Parkzeit statt - der
// Preis wurde bereits vorher im GET-Flow ermittelt und in amount_due gespeichert.
const amountDue = parseFloat(session.amount_due) || 0;
const amountPaid = parseFloat(session.amount_paid) || 0;
msg._open_amount_before = Math.max(0, Math.round((amountDue - amountPaid) * 100) / 100);

// Zahlungssimulation: offenen Betrag als vollstaendig bezahlt eintragen
msg.topic = "UPDATE parking_sessions SET " +
  "amount_paid = amount_due, " +
  "payment_time = datetime('now'), " +
  "exit_valid_until = datetime('now', '+15 minutes') " +
  "WHERE id = " + msg._patch_id + " AND exit_time IS NULL;";
return msg;

if (msg.statusCode) return msg;
msg.topic = "SELECT id, plate, amount_due, amount_paid, payment_time, exit_valid_until, exit_time " +
  "FROM parking_sessions WHERE id = " + msg._patch_id + ";";
return msg;
